const L = $json;
const issues = [];
if ((L.load_time_ms||0) > 3000) issues.push('svetainė lėta (' + Math.round(L.load_time_ms/1000) + 's)');
if (L.ssl_valid === false) issues.push('SSL negalioja');
if (L.mobile_friendly === false) issues.push('neoptimizuota mobiliam');
const tech = (L.expand?.tech_stack_via_lead || []).map(t => t.name + (t.version?' '+t.version:'')).join(', ');
return [{ json: { ...L, _issues: issues.join(', '), _tech_list: tech } }];

