parameters.functionCode:
const claudeResp = $json;
const text = claudeResp.content?.[0]?.text || '{}';
let parsed = { subject: '', body: '' };
try { parsed = JSON.parse(text); } catch(e) { parsed = { subject: 'Pastebėjimas apie jūsų svetainę', body: text }; }

const trackingId = crypto.randomUUID();
const pixel = `<img src="https://crm.oktoja.lt/api/tracking/pixel/${trackingId}.gif" width="1" height="1" style="display:none"/>`;
const bodyHtml = parsed.body.replace(/\n/g, '<br>') + '<br><br>—<br>Tomas<br>Oktoja' + pixel;

const lead = $('Paruošti kontekstą').item.json;

return [{ json: {
  lead: lead.id,
  subject: parsed.subject,
  body_html: bodyHtml,
  body_text: parsed.body,
  from_email: 'tomas@oktoja.lt',
  to_email: lead.contact_email,
  status: 'queued',
  tracking_id: trackingId,
  ai_generated: true,
  ai_model: 'claude-haiku-4-5',
}}];
